def clean_number(value):
    if pd.isna(value):
        return pd.NA
    value = str(value).strip()
    if value in ["-", "", "nan", "NaN"]:
        return pd.NA
    value = value.replace(",", "")
    try:
        return float(value)
    except ValueError:
        return pd.NA

